// ── web/client/bgwsClient.ts ─────────────────────────────────────────────
// The browser side of the Rust host (RUST_ENGINE.md §16): a typed client for
// bgws-server's WebSocket. It is the boundary the React screens bind to in
// place of the TypeScript runner: frames (truth for the umpire, else a
// side's belief), the event feed, questions for a person's seat, and the
// controls. The message types come from Rust (`../types`, generated by
// ts-rs), so the two sides cannot drift.

import type { FrameView } from "../types/FrameView";
import type { Question } from "../types/Question";
import type { Side } from "../types/Side";
import type { Viewer } from "../types/Viewer";

/** One feed line. */
export interface FeedEvent {
  clock: string;
  kind: string;
  text: string;
}

/**
 * A view of the game. `t` is the frame's simulated seconds and `live` the
 * game's; `scrub` marks a keyframe shown while looking back.
 */
export interface FrameMsg {
  kind: "frame";
  frame: FrameView;
  t: number;
  live: number;
  scrub?: boolean;
}

/** What the server sends. */
export type Outbound =
  | FrameMsg
  | { kind: "branched"; t: number }
  | { kind: "report"; title: string; text: string }
  | { kind: "events"; events: FeedEvent[] }
  | { kind: "questions"; questions: Question[] }
  | { kind: "status"; text: string };

/** What the server accepts. */
export type Inbound =
  | { kind: "play" }
  | { kind: "pause" }
  | { kind: "speed"; speed: number }
  | { kind: "viewer"; viewer: Viewer }
  | { kind: "answer"; question: number; choice: string }
  | { kind: "command"; side: Side; plan: unknown }
  | { kind: "seat"; side: Side; seat: "planner" | "person" | "rules" }
  | { kind: "seek"; t: number }
  | { kind: "live" }
  | { kind: "branch"; t: number }
  | { kind: "save" }
  | { kind: "why"; unit: string }
  | { kind: "review" }
  | { kind: "detect"; observer: string; target: string };

export interface ClientHandlers {
  onFrame?: (frame: FrameView, at: { t: number; live: number; scrub: boolean }) => void;
  /** The game restarted at `t`: drop anything shown from after it. */
  onBranched?: (t: number) => void;
  /** A `why` or `review` answer: Markdown over the events this viewer may see. */
  onReport?: (title: string, text: string) => void;
  onEvents?: (events: FeedEvent[]) => void;
  onQuestions?: (questions: Question[]) => void;
  onStatus?: (text: string) => void;
}

/** A connection to a running `bgws-server`. */
export class BgwsClient {
  private ws: WebSocket;
  private queue: Inbound[] = [];
  /** The latest frame, for screens that poll rather than subscribe. */
  frame: FrameView | null = null;
  /** Questions waiting for the person at this seat. */
  questions: Question[] = [];

  private readonly handlers: ClientHandlers;

  constructor(url: string, handlers: ClientHandlers = {}) {
    this.handlers = handlers;
    this.ws = new WebSocket(url);
    this.ws.onopen = () => {
      for (const m of this.queue.splice(0)) this.ws.send(JSON.stringify(m));
    };
    this.ws.onmessage = (ev) => this.receive(JSON.parse(String(ev.data)) as Outbound);
    this.ws.onclose = () => this.handlers.onStatus?.("disconnected");
  }

  private receive(m: Outbound): void {
    switch (m.kind) {
      case "frame":
        this.frame = m.frame;
        this.handlers.onFrame?.(m.frame, { t: m.t, live: m.live, scrub: !!m.scrub });
        break;
      case "branched":
        this.handlers.onBranched?.(m.t);
        break;
      case "report":
        this.handlers.onReport?.(m.title, m.text);
        break;
      case "events":
        this.handlers.onEvents?.(m.events);
        break;
      case "questions":
        this.questions = m.questions;
        this.handlers.onQuestions?.(m.questions);
        break;
      case "status":
        this.handlers.onStatus?.(m.text);
        break;
    }
  }

  private send(m: Inbound): void {
    if (this.ws.readyState === WebSocket.OPEN) this.ws.send(JSON.stringify(m));
    else this.queue.push(m);
  }

  play(): void {
    this.send({ kind: "play" });
  }
  pause(): void {
    this.send({ kind: "pause" });
  }
  /** × real time. The clock still waits, in simulated time, for every answer. */
  speed(speed: number): void {
    this.send({ kind: "speed", speed });
  }
  view(viewer: Viewer): void {
    this.send({ kind: "viewer", viewer });
  }
  /** Answer a question for the side this person plays. */
  answer(question: Question, choice: string): void {
    this.send({ kind: "answer", question: Number(question.id), choice });
  }
  /** Give a side's orders as an HQ plan (the orders schema, `plan_schema` on HQ questions). */
  command(side: Side, plan: unknown): void {
    this.send({ kind: "command", side, plan });
  }
  /** Who sits in a side's HQ seat. */
  seat(side: Side, seat: "planner" | "person" | "rules"): void {
    this.send({ kind: "seat", side, seat });
  }
  /** Look back to the keyframe at or before `t` simulated seconds (pauses the game). */
  seek(t: number): void {
    this.send({ kind: "seek", t });
  }
  /** Back to the live game. */
  live(): void {
    this.send({ kind: "live" });
  }
  /** "What if": restart the game at `t` by replaying its record there, then play on. */
  branch(t: number): void {
    this.send({ kind: "branch", t });
  }
  /** Write the game record on the server (`--record`). */
  save(): void {
    this.send({ kind: "save" });
  }
  /** What happened to a unit (by label), with the figures behind it. */
  why(unit: string): void {
    this.send({ kind: "why", unit });
  }
  /** The after-action review so far. */
  review(): void {
    this.send({ kind: "review" });
  }
  /** Why one unit would see another now, with every factor (umpire view only: it reads truth). */
  detect(observer: string, target: string): void {
    this.send({ kind: "detect", observer, target });
  }
  close(): void {
    this.ws.close();
  }
}
